#!/usr/bin/env python3
"""Was a snapshot generated by one run.py, or by several at once?

`run.py` is strictly sequential: one `subprocess.run`, then one
`save_snapshot`, per cell. Inside a single invocation at most one CLI call can
be in flight. But rounds 16 and 17 were generated one case per process at
5-way concurrency, each process owning its own shard file, and the shards were
merged afterwards - so the merged snapshot describes an execution regime no
single process could have produced, and until #120 nothing in the file said so.

Reconstructing is possible because every run records when it finished and how
long it took: the call occupied `[generated_at - duration_ms, generated_at]`.
Sweeping those windows for maximum overlap recovers how many CLI invocations
were actually running at once. A summed-duration to wall-clock ratio above 1 is
the same fact stated without a sweep - more CLI-seconds were consumed than
elapsed.

Grouped by arm and generation day, because a carried arm was generated days
earlier by a different pass and interleaving it with fresh runs would report
overlap that never happened.

The reconstruction is conservative in two ways, so a reported overlap is a
floor and never an artefact. `duration_ms` is the CLI's own figure for the
attempt that was recorded, so a cell that failed and was retried contributes
one window where two calls occurred. And second-granularity timestamps make a
call that ends exactly when the next begins read as sequential.

Since #120 `run.py` also stamps a per-run `generator` id, which makes the same
finding available without any reconstruction: two ids inside one arm-day is
two processes, whatever the timestamps say.
"""
import argparse
import glob
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SNAPSHOTS = ROOT / "evals" / "snapshots"


def _epoch(ts):
    try:
        return datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc).timestamp()
    except (TypeError, ValueError):
        return None


def windows(runs):
    """[(start, end, run)] for every run that records both fields it needs.

    A run with no duration is dropped rather than treated as an instant: the
    sweep resolves ties by closing intervals before opening them, which is what
    makes a call ending exactly when the next begins read as sequential, and a
    zero-width window would close before it opened. Failed runs record 0 ms, so
    they are the ones this drops - and they carry no evidence of overlap
    anyway.
    """
    out = []
    for r in runs:
        end = _epoch(r.get("generated_at"))
        if end is None:
            continue
        dur = r.get("duration_ms")
        if not isinstance(dur, (int, float)) or dur <= 0:
            continue
        out.append((end - dur / 1000.0, end, r))
    return out


def _merge(intervals):
    """Union of one source's windows, so a source counts once at any instant."""
    out = []
    for start, end in sorted(intervals):
        if out and start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out


def max_in_flight(wins):
    """Peak simultaneous *sources*. Ends sort before starts, so touching is 1.

    A source is one `run.py` invocation, identified by the `generator` stamp,
    and a single invocation is sequential by construction - so its windows are
    merged before the sweep rather than counted individually. That matters
    because `generated_at` has one-second resolution: eight calls of 40 ms each
    inside the same second all carry the same timestamp and would otherwise
    read as eight processes.

    A run with no generator is its own source, which is every run committed
    before #120 and is what makes the historical reconstruction work at all.
    """
    by_source = {}
    for i, (start, end, r) in enumerate(wins):
        by_source.setdefault(r.get("generator") or ("?", i), []).append((start, end))
    events = []
    for intervals in by_source.values():
        for start, end in _merge(intervals):
            events.append((start, 1))
            events.append((end, -1))
    events.sort(key=lambda e: (e[0], e[1]))
    peak = cur = 0
    for _, delta in events:
        cur += delta
        peak = max(peak, cur)
    return peak


def groups(runs):
    """{(arm, day): [window]} - the unit a round was actually generated in."""
    out = {}
    for start, end, r in windows(runs):
        key = (r.get("arm"), (r.get("generated_at") or "")[:10])
        out.setdefault(key, []).append((start, end, r))
    return out


def carried_runs(snap, root=ROOT):
    """The runs this snapshot copied in rather than generated.

    A carried run's execution regime belongs to the pass that produced it. The
    control batch of 2026-08-12 was generated at 3-way concurrency and is
    carried into every round from 16 to 24, so charging it to the carrying
    round reports round 21 as concurrent when its own generation was strictly
    sequential - and round 20 against round 21 is the one comparison #120 most
    needs to keep straight.

    Identified by reading the named carry source and matching cell keys, not by
    trusting `carried_arms_from.arms`: an arm can be both carried and extended
    in the same file. `baseline-arm-n10.json` carries 30 baseline runs from
    2026-08-12 and then generates 190 more on 08-14 into the same arm, and an
    arm-level rule hides the 08-14 batch, which is the one running six
    invocations at once.

    One snapshot records the source as an absolute path from the machine that
    generated it, so the path is re-rooted onto this checkout when it does not
    resolve. Without that the file reads as uncarried in every clone but the
    maintainer's, which is a difference between what CI sees and what the
    author sees.

    An unresolvable source yields the empty set, so a run is charged to the
    snapshot holding it rather than quietly excused.
    """
    c = (snap.get("metadata") or {}).get("carried_arms_from") or {}
    path = c.get("path")
    if not path:
        return set()
    src = _resolve_source(path, root)
    if src is None:
        return set()
    try:
        source = json.loads(src.read_text())
    except (OSError, ValueError):
        return set()
    return {_cell(r) for r in source.get("runs", [])
            if isinstance(r, dict)}


def _resolve_source(path, root=ROOT):
    """The carry source as it exists in this checkout, or None."""
    src = Path(path)
    if not src.is_absolute():
        src = Path(root) / path
    if src.is_file():
        return src
    parts = Path(path).parts
    if "evals" in parts:
        src = Path(root).joinpath(*parts[parts.index("evals"):])
        if src.is_file():
            return src
    return None


def _cell(run):
    return (run.get("case"), run.get("arm"), run.get("model"), run.get("rep"),
            run.get("generated_at"))


def audit(snap):
    """One row per arm-day: n, wall, summed, ratio, peak overlap, generators."""
    rows = []
    carried = carried_runs(snap)
    for (arm, day), wins in sorted(groups(snap.get("runs", [])).items()):
        starts = [w[0] for w in wins]
        ends = [w[1] for w in wins]
        wall = max(ends) - min(starts)
        summed = sum(e - s for s, e, _ in wins)
        gens = sorted({w[2].get("generator") for w in wins
                       if w[2].get("generator")})
        rows.append({
            "arm": arm, "day": day, "n": len(wins),
            "wall_s": wall, "summed_s": summed,
            "ratio": (summed / wall) if wall > 0 else None,
            "max_in_flight": max_in_flight(wins),
            "generators": gens,
            # An arm-day that straddles the boundary counts as generated, so a
            # mixed batch is checked rather than excused.
            "carried": all(_cell(w[2]) in carried for w in wins),
        })
    return rows


def snapshot_max_in_flight(runs, carried=()):
    """The single number `run.py` stamps into metadata at write time.

    Max over arm-days rather than over the whole run list, for the same reason
    the table groups: runs generated last week overlap this week's in a naive
    sweep and did not overlap them in fact. `carried` is a set of cell keys
    from carried_runs(); those arm-days are dropped, so the number describes
    what this round generated.
    """
    per_group = [max_in_flight(w) for w in groups(runs).values()
                 if not all(_cell(x[2]) in carried for x in w)]
    return max(per_group) if per_group else 0


def declared(snap):
    """How many processes the operator said were in flight. 1 if unstated."""
    return snap.get("metadata", {}).get("concurrency_declared", 1) or 1


def _fmt(rows, path, limit):
    lines = []
    for r in rows:
        if r["n"] < limit:
            continue
        lines.append("%-46s %-16s %-10s %4d  %7.1fm %7.1fm %6s  %2d  %-8s %s"
                     % (path, r["arm"] or "-", r["day"] or "-", r["n"],
                        r["wall_s"] / 60.0, r["summed_s"] / 60.0,
                        "-" if r["ratio"] is None else "%.2f" % r["ratio"],
                        r["max_in_flight"],
                        "carried" if r["carried"] else "generated",
                        ",".join(r["generators"]) or "-"))
    return lines


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("snapshots", nargs="*",
                    help="snapshot files; default every file under evals/snapshots")
    ap.add_argument("--min-runs", type=int, default=1,
                    help="skip arm-days with fewer runs than this (default 1)")
    ap.add_argument("--warn", action="store_true",
                    help="report and exit 0 even when a snapshot exceeds its "
                         "declared concurrency")
    ap.add_argument("--include-carried", action="store_true",
                    help="also fail on carried arms, whose regime belongs to "
                         "the snapshot that generated them")
    ap.add_argument("--quiet", action="store_true",
                    help="print only the arm-days that exceed their declaration")
    args = ap.parse_args()

    paths = args.snapshots or sorted(
        glob.glob(str(SNAPSHOTS / "**" / "*.json"), recursive=True))
    header = ("%-46s %-16s %-10s %4s  %8s %8s %6s  %2s  %-8s %s"
              % ("snapshot", "arm", "day", "n", "wall", "summed", "ratio",
                 "fl", "origin", "generators"))
    body, bad = [], []
    for p in paths:
        try:
            snap = json.loads(Path(p).read_text())
        except (OSError, ValueError):
            continue
        if not isinstance(snap, dict) or not isinstance(snap.get("runs"), list):
            continue
        rel = os.path.relpath(p, str(ROOT))
        limit = declared(snap)
        rows = audit(snap)
        # A carried arm is another snapshot's finding. It shows in the table
        # marked `carried` and does not fail this file.
        over = [r for r in rows if r["max_in_flight"] > limit
                and r["n"] >= args.min_runs
                and (args.include_carried or not r["carried"])]
        bad.extend(_fmt(over, rel, args.min_runs))
        if not args.quiet:
            body.extend(_fmt(rows, rel, args.min_runs))

    print(header)
    for line in (bad if args.quiet else body):
        print(line)

    if bad:
        print("\n%d arm-day(s) ran more CLI invocations at once than the "
              "snapshot declares. Generate with --concurrency N if that was "
              "deliberate, so the number is recorded rather than "
              "reconstructed." % len(bad))
    else:
        print("\nno arm-day exceeds its declared concurrency")
    return 0 if (not bad or args.warn) else 1


if __name__ == "__main__":
    sys.exit(main())
